CREATE OR REPLACE FUNCTION fn_validate_recipient_age()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.age_count < OLD.age_count THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_validate_recipient_age
BEFORE UPDATE ON recipients_demographics
FOR EACH ROW
EXECUTE FUNCTION fn_validate_recipient_age();

